from pathlib import Path
import json
from figurelib import *
p=Path(__file__).resolve().parents[1];d=json.loads((p/'examples/results.json').read_text());items=[]
def add(n,f,s):items.append((n,f,s))
f=Fig('都说空闲，路上却还有工作')
f.node(200,220,'R空闲',300,fill=LIGHT,outline=GRAY);f.node(860,220,'A空闲',300,fill=LIGHT,outline=GRAY);f.arrow((360,220),(700,220));f.node(531,470,'工作消息',350);f.arrow((531,420),(650,260));add('01-inflight.png',f,'本地空闲不覆盖尚未到达的工作消息。')
f=Fig('工作向外走，回执往回走')
f.node(160,300,'R',180);f.node(900,300,'A',180);f.arrow((270,220),(790,220),BLUE);f.arrow((790,420),(270,420),TEAL);f.text(531,150,'工作',fill=BLUE,anchor='mm');f.text(531,510,'回执',fill=TEAL,anchor='mm');add('02-two-messages.png',f,'区分业务工作消息与检测用回执，回执不产生新业务任务。')
f=Fig('发送一项，先记一笔未结账')
f.table(['动作','未结账'],d['single_debt'],widths=[620,354]);add('03-debt.png',f,'欠账在发送时建立，收到回执才消除，覆盖工作和回执的传输时间。')
f=Fig('首次接到工作，记住来处')
f.node(531,190,'R',220);f.node(250,470,'A',220);f.node(810,470,'B',220);f.arrow((475,240),(290,420));f.arrow((585,240),(770,420));f.text(250,620,'父节点R',44,anchor='mm');f.text(810,620,'父节点R',44,anchor='mm');add('04-tree.png',f,'首次工作建立参与树；父关系是回执责任，不是固定网络拓扑。')
f=Fig('A又给B送工作，先别改父亲')
f.node(531,180,'R',220);f.node(220,480,'A',220);f.node(840,480,'B',220);f.arrow((475,230),(260,430));f.arrow((585,230),(800,430));f.arrow((340,480),(720,480),ORANGE);f.text(531,620,'追加工作：A到B',44,anchor='mm',fill=ORANGE);add('05-cross.png',f,'橙色交叉边是追加工作，B仍保留首次父边R。')
f=Fig('B回追加回执，却还没有做完')
f.node(220,220,'A',220);f.node(840,220,'B',220);f.arrow((720,220),(340,220),TEAL);f.text(531,145,'追加回执',44,TEAL,anchor='mm');f.queue(['任务b','任务c'],y=470,x=360);f.text(531,640,'B仍由父节点R负责',44,anchor='mm');add('06-early-ack.png',f,'早回执只解除追加发送者的账；本地未完成工作仍被首次父边兜住。')
f=Fig('叶子收缩：自己和下游都清空')
f.node(531,190,'R',220);f.node(250,460,'A',220,fill=LIGHT,outline=GRAY);f.node(810,460,'B',220);f.arrow((290,410),(475,240),TEAL);f.arrow((585,240),(770,410));f.text(250,620,'A回父回执',44,TEAL,anchor='mm');f.text(810,620,'B仍在工作',44,anchor='mm');add('07-contract.png',f,'A退出不使整个系统结束，R还持有对B的未结账。')
f=Fig('最后一个回执，也要真的到达')
f.node(200,220,f'R欠{len(d["trace"][-2]["nodes"]["R"]["out"])}',300);f.node(860,220,'B空闲',300,fill=LIGHT,outline=GRAY);f.arrow((700,220),(360,220),TEAL);f.text(531,390,'回执在路上',44,TEAL,anchor='mm');f.node(531,600,f'到达后：R欠{len(d["trace"][-1]["nodes"]["R"]["out"])}',540,fill=MINT,outline=TEAL);add('08-last-ack.png',f,'全体业务已停与根已获知结束不是同一瞬间；迟报比错报安全。')
f=Fig('每一步的未结账数量')
f.table(['步骤','R','A','B'],d['debt_rows'],widths=[244,243,243,244]);add('09-ledger.png',f,'从实际消息轨迹读取，追加消息使A暂时增加一笔而根始终等着父边回执。')
f=Fig('每封信都等做完，可能互相等')
f.node(250,300,'A',240);f.node(810,300,'B',240);f.arrow((380,220),(680,220),ORANGE);f.arrow((680,440),(380,440),ORANGE);f.text(531,145,'A等B回执',44,anchor='mm');f.text(531,550,'B等A回执',44,anchor='mm');add('10-cycle.png',f,'任意业务通信图可有环，把每条消息都作父责任会形成相互等待。')
f=Fig('三个零，不能混成同一个')
f.table(['为零的东西','能够说明'],[['本地队列','现在没活'],['本地未结账','发出的账已回'],['根两者都零','本轮结束']],widths=[470,504]);add('11-zeros.png',f,'最后一行仅在本文协议不变量和通信前提满足时成立。')
f=Fig('有限模型的全部可达状态')
e=d['exploration'];f.table(['检查','结果'],[['不同状态',e['states']],['终止状态',e['terminal_states']],['最多未结账',e['max_outstanding']],['错误宣布',e['false_positive']]],widths=[620,354]);add('12-explore.png',f,'实际穷举37个去重状态，未见错误宣布；不把有限模型冒充一般形式证明。')
emit(p,items)
